110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        HttpHeaders headers = new HttpHeaders();
114	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
115	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
116	        owner.setTelephone(telephone);
117	        String email = EmailNormalizer.normalize(owner.getEmail());
118	        owner.setEmail(email);
119	        owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
120	        LocalDate effectiveRegistrationDate =
121	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
122	        owner.setRegistrationDate(RegistrationDateNormalizer.normalize(effectiveRegistrationDate));
123	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
124	            .anyMatch(existing -> telephone.equals(TelephoneNormalizer.toE164(existing.getTelephone())));
125	        if (telephoneInUse) {
126	            throw new DuplicateTelephoneException(
127	                "telephone " + telephone + " is already used by another owner");
128	        }
129	        if (email != null) {
130	            boolean emailInUse = this.clinicService.findAllOwners().stream()
131	                .map(Owner::getEmail)
132	                .filter(existing -> existing != null)
133	                .anyMatch(existing -> email.equalsIgnoreCase(existing));
134	            if (emailInUse) {
135	                throw new DuplicateEmailException(
136	                    "email " + email + " is already used by another owner");
137	            }
138	        }
139	        this.clinicService.createOwner(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
140	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
141	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
142	            ownerMapper.membershipLevel(owner));
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        headers.setLocation(UriComponentsBuilder.newInstance()
