83	        return petRepository.findAll(pageable);
84	    }
85	
86	    @Override
87	    @Transactional
88	    public void deletePet(Pet pet) throws DataAccessException {
89	        petRepository.delete(pet);
90	    }
91	
92	    @Override
93	    @Transactional(readOnly = true)
94	    public Visit findVisitById(int visitId) throws DataAccessException {
95	        return findEntityById(() -> visitRepository.findById(visitId));
96	    }
