254	    @Override
255	    @Transactional
256	    public void createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
257	        rejectWhenDailyLimitReached(owner);
258	        rejectWhenCityAtCapacity(owner);
259	        List<Owner> householdMembers = assignHousehold(owner, sharesHousehold);
260	        owner.setHouseholdMemberCount(householdMembers.size() + 1);
261	        if (owner.getCustomerCode() == null) {
262	            owner.setCustomerCode(nextCustomerCode(owner));
263	        }
264	        if (owner.getNamesakeCount() == null) {
265	            owner.setNamesakeCount(countNamesakes(owner));
266	        }
267	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
268	        ownerRepository.save(owner);
269	    }
270	
271	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
272	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
273	
274	    /**
275	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
276	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
277	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
278	     * today by the controller, determines which day is counted — the same accumulation path as the
279	     * daily-limit rule.
280	     */
281	    private boolean exceedsBulkSignupThreshold(Owner owner) {
282	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
283	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
284	    }
285	
286	    /**
287	     * Count the existing owners that already share this owner's first name and last name,
288	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
289	     * before the owner is persisted, so it reflects the owners present at creation time.
290	     */
291	    private int countNamesakes(Owner owner) {
292	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
293	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
294	        return (int) ownerRepository.findAll().stream()
295	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
296	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
297	            .count();
298	    }
299	
300	    /**
301	     * Reconcile the owner's household and return its existing members. Owners are in the same
302	     * household when their last name and address match (compared case-insensitively with collapsed
303	     * whitespace). When another owner already lives there, the create is rejected with
304	     * {@link DuplicateHouseholdException} unless {@code sharesHousehold} is set, in which case the
305	     * new owner and every existing member are given the same stable shared {@code householdId}.
306	     * The returned list is the existing members that make up this owner's household (empty when the
307	     * owner lives alone), so callers can derive the household size after this create.
308	     */
309	    private List<Owner> assignHousehold(Owner owner, boolean sharesHousehold) {
310	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
311	        String address = AddressNormalizer.canonical(owner.getAddress());
312	        List<Owner> householdMembers = ownerRepository.findAll().stream()
313	            .filter(existing -> lastName.equals(IdentityNormalizer.normalize(existing.getLastName()))
314	                && address.equals(AddressNormalizer.canonical(existing.getAddress())))
315	            .toList();
316	        if (householdMembers.isEmpty()) {
317	            return householdMembers;
318	        }
319	        if (!sharesHousehold) {
320	            throw new DuplicateHouseholdException(
321	                "an owner with last name " + owner.getLastName() + " already lives at " + owner.getAddress());
322	        }
323	        String householdId = householdMembers.stream()
324	            .map(Owner::getHouseholdId)
325	            .filter(Objects::nonNull)
326	            .findFirst()
327	            .orElseGet(() -> deriveHouseholdId(lastName, address));
328	        owner.setHouseholdId(householdId);
329	        for (Owner member : householdMembers) {
330	            if (!householdId.equals(member.getHouseholdId())) {
331	                member.setHouseholdId(householdId);
332	                ownerRepository.save(member);
333	            }
334	        }
335	        return householdMembers;
336	    }
337	
338	    /**
339	     * Derive a stable, shared household identifier from the normalized last name and address, so
340	     * every owner in the same household deterministically maps to the same value.
341	     */
342	    private static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
343	        String key = normalizedLastName + "\n" + normalizedAddress;
344	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
345	    }
346	
347	    /** Maximum number of owners that may be created on any single day (by registration date). */
348	    private static final long DAILY_OWNER_LIMIT = 100L;
349	
350	    /**
351	     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
352	     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
353	     * reflects the owners present at creation time. The new owner's own registration date, defaulted
354	     * to today by the controller, determines which day the limit is checked against.
355	     */
356	    private void rejectWhenDailyLimitReached(Owner owner) {
357	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
358	        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
359	            throw new DailyOwnerLimitExceededException(
360	                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
361	        }
362	    }
363	
364	    /**
365	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
366	     * before the owner is persisted, so it reflects the owners present at creation time.
367	     */
368	    private long countOwnersRegisteredOn(LocalDate day) {
369	        return ownerRepository.findAll().stream()
370	            .filter(existing -> day.equals(existing.getRegistrationDate()))
371	            .count();
372	    }
373	
374	    /** Maximum number of owners allowed to live in any single city. */
375	    private static final long CITY_CAPACITY = 50L;
376	
377	    /**
378	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
379	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
380	     * is persisted, so it reflects the owners present at creation time.
381	     */
382	    private void rejectWhenCityAtCapacity(Owner owner) {
383	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
384	            throw new CityCapacityExceededException(
385	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
386	        }
387	    }
388	
389	    /**
390	     * Count the existing owners that already live in this owner's city, compared
391	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
392	     * owner is persisted, so it reflects the owners present at creation time.
393	     */
394	    private long countOwnersInCity(Owner owner) {
395	        String city = IdentityNormalizer.normalize(owner.getCity());
396	        return ownerRepository.findAll().stream()
397	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
398	            .count();
399	    }
400	
401	    /**
402	     * Builds the customer code {@code '<CITY3>-<LAST3>-<NNNN>'}: the upper-cased first
403	     * three letters of the owner's {@code city}, a hyphen, the upper-cased first three
404	     * letters of {@code lastName}, a hyphen, and a 4-digit zero-padded per-city sequence
405	     * equal to one more than the number of owners already in that city (compared
406	     * case-insensitively with collapsed whitespace).
407	     */
408	    private String nextCustomerCode(Owner owner) {
409	        String city3 = prefix3(owner.getCity());
410	        String last3 = prefix3(owner.getLastName());
411	        long sequence = countOwnersInCity(owner) + 1L;
412	        return String.format("%s-%s-%04d", city3, last3, sequence);
413	    }
414	
415	    /**
416	     * Returns the upper-cased first three letters of {@code value}, or fewer when the value
417	     * is shorter; a {@code null} value yields an empty string.
418	     */
419	    private static String prefix3(String value) {
420	        String name = value == null ? "" : value;
421	        return name.substring(0, Math.min(3, name.length())).toUpperCase();
422	    }
423	
