11	
12	import java.util.Collection;
13	import java.util.List;
14	import java.util.Map;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    Owner toOwner(OwnerDto ownerDto);
32	
33	    /**
34	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
35	     */
36	    default String displayName(Owner owner) {
37	        if (owner == null) {
38	            return null;
39	        }
40	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
41	        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
42	        return lastName + ", " + firstName;
43	    }
44	
45	    /**
46	     * Returns the upper-cased first letters of firstName and lastName,
47	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
48	     */
49	    default String initials(Owner owner) {
50	        if (owner == null) {
51	            return null;
52	        }
53	        StringBuilder sb = new StringBuilder();
54	        String firstName = owner.getFirstName();
55	        String lastName = owner.getLastName();
56	        if (firstName != null && !firstName.isEmpty()) {
57	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
58	        }
59	        if (lastName != null && !lastName.isEmpty()) {
60	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
61	        }
62	        return sb.toString();
63	    }
64	
65	    /**
66	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
67	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
68	     * Returns {@code null} unless both the customer code and registration date are present.
69	     */
70	    default String membershipNumber(Owner owner) {
71	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
72	            return null;
73	        }
74	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
75	        return owner.getCustomerCode() + "-M" + yy;
76	    }
77	
78	    /**
79	     * Returns the owner's numeric membership level. Starts at {@code 1}; adds {@code 1} when an
80	     * email address is present; adds {@code 1} when the owner has no namesakes (namesakeCount is
81	     * 0); capped at {@code 3} (level 4 is reserved for tenure).
82	     */
83	    default Integer membershipLevel(Owner owner) {
84	        if (owner == null) {
85	            return null;
86	        }
87	        int level = 1;
88	        String email = owner.getEmail();
89	        if (email != null && !email.isEmpty()) {
90	            level++;
91	        }
92	        Integer namesakeCount = owner.getNamesakeCount();
93	        if (namesakeCount != null && namesakeCount == 0) {
94	            level++;
95	        }
96	        return Math.min(level, 3);
97	    }
98	
99	    /** Fixed city-to-region table used to derive an owner's locality. */
100	    Map<String, String> CITY_REGION = Map.of(
101	        "Sydney", "NSW",
102	        "Melbourne", "VIC",
103	        "Brisbane", "QLD");
104	
105	    /**
106	     * Derives the owner's locality (region) from the city using the fixed city-to-region
107	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
108	     * Returns {@code "UNKNOWN"} when the city is {@code null} or not in the table.
109	     */
110	    default String locality(Owner owner) {
111	        if (owner == null) {
112	            return null;
113	        }
114	        String city = owner.getCity();
115	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
116	    }
117	
118	    /**
119	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
120	     * on its registration day at creation time). A {@code null} stored value is treated as
